# Distribution checks. Reference values are never regenerated by the analysis.
public_assert <- function(ok, message) if (!isTRUE(ok)) stop(message, call. = FALSE)
public_sha <- function(path) digest::digest(file = path, algo = "sha256", serialize = FALSE)
public_check_manifest <- function(root) {
  m <- read.csv(file.path(root, "distribution_manifest.csv"), stringsAsFactors = FALSE)
  public_assert(nrow(m) > 40L && !anyDuplicated(m$path), "Distribution manifest is empty or duplicated.")
  public_assert(all(!grepl("(^[/\\\\]|^[A-Za-z]:|(^|[/\\\\])\\.\\.([/\\\\]|$))", m$path)), "Unsafe distribution manifest path.")
  for (i in seq_len(nrow(m))) {
    p <- file.path(root, m$path[i])
    public_assert(file.exists(p) && identical(public_sha(p), m$sha256[i]), paste("Distribution file missing or changed:", m$path[i]))
  }
  invisible(TRUE)
}
public_compare <- function(root, stages = c("original", "secondary", "strengthening"), write_report = TRUE) {
  m <- read.csv(file.path(root, "reference_manifest.csv"), stringsAsFactors = FALSE)
  m <- m[m$stage %in% stages, , drop = FALSE]
  public_assert(nrow(m) > 0 && all(stages %in% m$stage), "Reference manifest does not cover requested stages.")
  result <- vector("list", nrow(m))
  for (i in seq_len(nrow(m))) {
    row <- m[i, ]; ref <- file.path(root, row$reference); actual <- file.path(root, row$output)
    public_assert(file.exists(ref) && file.exists(actual), paste("Required reference/output missing:", row$reference, row$output))
    public_assert(identical(public_sha(ref), row$sha256), paste("Reference changed:", row$reference))
    if (row$type == "csv") {
      expected <- read.csv(ref, check.names = FALSE, stringsAsFactors = FALSE, na.strings = c("", "NA"))
      observed <- read.csv(actual, check.names = FALSE, stringsAsFactors = FALSE, na.strings = c("", "NA"))
    } else if (row$type == "covariance") {
      expected <- read.csv(ref, check.names = FALSE, stringsAsFactors = FALSE)
      V <- readRDS(actual)$result$coefficient_covariance
      observed <- data.frame(term = rownames(V), V, check.names = FALSE, row.names = NULL)
    } else if (row$type == "json") {
      expected <- jsonlite::read_json(ref, simplifyVector = TRUE)
      z <- jsonlite::read_json(actual, simplifyVector = TRUE)
      public_assert(all(names(expected) %in% names(z)), "JSON output is missing a reference field.")
      observed <- z[names(expected)]
    } else stop("Unknown reference type: ", row$type, call. = FALSE)
    if (row$type %in% c("csv", "covariance")) {
      public_assert(identical(dim(observed), dim(expected)) && identical(names(observed), names(expected)),
        paste("Reference table shape or column order differs:", row$output))
      if (row$type == "covariance") public_assert(identical(observed$term, expected$term), "Covariance term labels differ.")
    }
    matched <- isTRUE(all.equal(observed, expected, tolerance = 1e-9, check.attributes = FALSE))
    public_assert(matched, paste("Scientific reference differs:", row$output, row$reference))
    result[[i]] <- data.frame(stage = row$stage, reference = row$reference, output = row$output,
      comparison = row$type, numeric_tolerance = 1e-9, matched = matched)
  }
  result <- do.call(rbind, result)
  if (write_report) {
    dir.create(file.path(root, "outputs"), showWarnings = FALSE)
    write.csv(result, file.path(root, "outputs/reproduction_comparison.csv"), row.names = FALSE)
  }
  message("Matched ", nrow(result), " independent aggregate reference files for ", paste(stages, collapse = ", "), ".")
  invisible(result)
}
public_dependencies <- function(root) {
  public_assert(as.character(getRversion()) == "4.5.1", "Use the pinned R 4.5.1 runtime.")
  m <- read.csv(file.path(root, "scripts/dependency_versions.csv"), stringsAsFactors = FALSE)
  for (i in seq_len(nrow(m))) {
    public_assert(requireNamespace(m$package[i], quietly = TRUE), paste("Missing dependency:", m$package[i]))
    public_assert(utils::compareVersion(as.character(packageVersion(m$package[i])), m$version[i]) == 0,
      paste("Dependency version differs:", m$package[i], "requires", m$version[i]))
  }
  invisible(TRUE)
}
